<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_finance.view');$pdo=db();$projectId=(int)($_GET['project_id']??0);$project=$projectId?pm_fetch_project($pdo,$projectId):null;$projects=pm_project_options($pdo);$where=$projectId?'WHERE e.project_id=?':'';$s=$pdo->prepare("SELECT e.*,p.name project_name FROM project_expenses e JOIN projects p ON p.id=e.project_id $where ORDER BY e.expense_date DESC,e.id DESC");$s->execute($projectId?[$projectId]:[]);$rows=$s->fetchAll();$totals=[];$bill=[];$cats=[];foreach($rows as$r){$totals[$r['currency']]=($totals[$r['currency']]??0)+(float)$r['amount'];if($r['billable'])$bill[$r['currency']]=($bill[$r['currency']]??0)+(float)$r['amount'];$cat=$r['category']?:'General';$cats[$cat]=($cats[$cat]??0)+(float)$r['amount'];}arsort($cats);$pageTitle='Costos de proyectos';require __DIR__.'/includes/header.php';if($project)echo pm_project_tabs($projectId,'expenses');?>
<div class="project-hero compact"><div><span class="eyebrow">CENTRO DE COSTOS</span><h2>Costos y gastos de proyectos</h2><p>Separa gastos internos, importes refacturables y categorías para entender dónde se usa el presupuesto.</p></div><div class="actions"><?php if(has_permission('project_finance.manage')):?><a class="btn btn-primary" href="project_expense_form.php<?=$projectId?'?project_id='.$projectId:''?>">+ REGISTRAR GASTO</a><?php endif;?><form method="get"><select name="project_id" onchange="this.form.submit()"><option value="0">Todos los proyectos</option><?php foreach($projects as$p):?><option value="<?=$p['id']?>" <?=$projectId===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></form></div></div><div class="cost-summary"><?php foreach(['USD','BRL','CLP'] as$c):$v=$totals[$c]??0;$bv=$bill[$c]??0;?><div class="cost-kpi"><small>Total <?=$c?></small><strong><?=e(format_money($v,$c))?></strong><span><?=e(format_money($bv,$c))?> refacturable · <?=e(format_money(max(0,$v-$bv),$c))?> interno</span></div><?php endforeach;?><div class="cost-kpi"><small>Movimientos</small><strong><?=count($rows)?></strong><span><?=count($cats)?> categorías</span></div></div><?php if($cats):?><div class="cost-category-grid"><?php foreach(array_slice($cats,0,8,true) as$cat=>$v):?><div class="cost-category"><small><?=e($cat)?></small><strong><?=e(number_format($v,2,',','.'))?></strong><small>Acumulado referencial</small></div><?php endforeach;?></div><?php endif;?><section class="panel"><div class="panel-header"><div><h2>Detalle de movimientos</h2><span class="table-sub">Proyecto, categoría, concepto, importe y tipo de costo.</span></div></div><div class="table-wrap"><table class="data-table cost-table"><thead><tr><th>Fecha</th><th>Proyecto</th><th>Categoría</th><th>Concepto</th><th>Importe</th><th>Tipo</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">Sin gastos registrados.</td></tr><?php endif;?><?php foreach($rows as$r):?><tr><td><?=e(pm_date($r['expense_date']))?></td><td><strong><?=e($r['project_name'])?></strong></td><td><span class="badge badge-blue"><?=e($r['category']?:'General')?></span></td><td><?=e($r['description']?:'Sin descripción')?></td><td><strong><?=e(format_money($r['amount'],$r['currency']))?></strong></td><td><?=$r['billable']?'<span class="badge badge-green">Refacturable</span>':'<span class="badge badge-gray">Interno</span>'?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/includes/footer.php';?>
